void Bitmap(std::filesystem::path const& path,std::vector<uint32_t> const& pixels,unsigned w,unsigned h){BITMAPFILEHEADER a{};BITMAPINFOHEADER b{};a.bfType=0x4d42;a.bfOffBits=sizeof(a)+sizeof(b);a.bfSize=a.bfOffBits+w*h*4;b.biSize=sizeof(b);b.biWidth=LONG(w);b.biHeight=-LONG(h);b.biPlanes=1;b.biBitCount=32;std::ofstream f(path,std::ios::binary);f.write(reinterpret_cast<char*>(&a),sizeof(a));f.write(reinterpret_cast<char*>(&b),sizeof(b));f.write(reinterpret_cast<char const*>(pixels.data()),pixels.size()*4);Need(bool(f),"Replay bitmap write");}
Camera Shift(Camera camera,float x,float y,unsigned w,unsigned h){auto* m=reinterpret_cast<float*>(&camera.viewProjection);for(unsigned r=0;r<4;++r){m[r*4]+=m[r*4+3]*x*2/float(w);m[r*4+1]-=m[r*4+3]*y*2/float(h);}return camera;}
